    @Test
    void discarded_book_is_returned_as_discarded() throws Exception {
        String bookId = registerBook("폐기 처리 책");

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("폐기 처리 책"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarded_book_cannot_be_loaned() throws Exception {
        String bookId = registerBook("폐기 후 대출 시도");
        String memberId = registerMember();

        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void book_on_loan_cannot_be_discarded_until_returned() throws Exception {
        String bookId = registerBook("대출 중 폐기 시도");
        String loanId = loanAndGetLoanId(bookId, registerMember());

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));

        mockMvc.perform(post("/loans/" + loanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(post("/books/" + bookId + "/discard"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

